files.content:
.root {
  --vt-surface: #fafcfd;
  --vt-surface-2: #f0f5f7;
  --vt-surface-deep: #e8f0f3;
  --vt-ink: #2c3e44;
  --vt-ink-soft: #5f7a84;
  --vt-on-deep: #2c3e44;
  --vt-accent: #5b7a8a;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #3d5561;
  --vt-accent-on-deep: #5b7a8a;
  --vt-line: #dce6ea;
  --vt-font-heading: "Fraunces", Georgia, serif;
  --vt-font-body: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
  font-family: var(--vt-font-body);
  font-size: 1rem;
  line-height: 1.7;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.root :where(h1, h2, h3, h4) {
  font-family: var(--vt-font-heading);
  font-weight: 400;
  line-height: 1.3;
  color: var(--vt-ink);
}

.root :where(p) {
  margin-bottom: 1rem;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
  transition: color 0.2s ease;
}

.container {
  width: 100%;
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 2rem;
}

.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--vt-surface);
  border-bottom: 1px solid var(--vt-line);
}

.navInner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 4rem;
}

.logo {
  font-family: var(--vt-font-heading);
  font-size: 1.25rem;
  color: var(--vt-ink);
}

.brand {
  display: inline-flex;
  align-items: center;
}

.navLinks {
  display: flex;
  gap: 2rem;
}

.navLinks a {
  font-size: 0.9375rem;
  color: var(--vt-ink-soft);
}

.navLinks a:hover {
  color: var(--vt-ink);
}

.hero {
  padding: 7rem 0 6rem;
  background: var(--vt-surface);
}

.heroGrid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 4rem;
  align-items: center;
}

.heroContent {
  max-width: 540px;
}

.tagline {
  font-size: 1.125rem;
  color: var(--vt-ink-soft);
  margin-bottom: 0.5rem;
}

.heroTitle {
  font-size: clamp(2.5rem, 5vw, 3.5rem);
  letter-spacing: -0.02em;
  margin-bottom: 1rem;
}

.heroDescription {
  font-size: 1.125rem;
  color: var(--vt-ink-soft);
  margin-bottom: 2rem;
  max-width: 480px;
}

.btnGroup {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.btnPrimary,
.btnSecondary {
  display: inline-block;
  padding: 0.875rem 1.75rem;
  font-family: var(--vt-font-body);
  font-size: 0.9375rem;
  font-weight: 500;
  text-align: center;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btnPrimary {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border: 1px solid var(--vt-accent);
}

.btnPrimary:hover {
  background: var(--vt-accent-ink);
  border-color: var(--vt-accent-ink);
}

.btnSecondary {
  background: transparent;
  color: var(--vt-ink);
  border: 1px solid var(--vt-line);
}

.btnSecondary:hover {
  background: var(--vt-surface-2);
  border-color: var(--vt-ink-soft);
  color: var(--vt-ink);
}

.heroVisual {
  display: flex;
  justify-content: center;
  align-items: center;
}

.albumShowcase {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}

.albumCover {
  position: relative;
  width: 280px;
  height: 280px;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 20px 60px color-mix(in srgb, var(--vt-ink) 15%, transparent), 0 8px 20px color-mix(in srgb, var(--vt-ink) 10%, transparent);
}

.albumCover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.albumReflection {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, color-mix(in srgb, var(--vt-on-accent) 20%, transparent) 0%, transparent 50%);
  pointer-events: none;
}

.visualizer {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 4px;
  height: 40px;
  padding: 1rem 2rem;
  background: var(--vt-on-deep);
  border: 1px solid var(--vt-line);
  border-radius: 8px;
}

.bar {
  width: 4px;
  background: var(--vt-accent);
  border-radius: 2px;
  height: 8px;
}

.bar:nth-child(1) { height: 12px; }
.bar:nth-child(2) { height: 20px; }
.bar:nth-child(3) { height: 16px; }
.bar:nth-child(4) { height: 28px; }
.bar:nth-child(5) { height: 24px; }
.bar:nth-child(6) { height: 32px; }
.bar:nth-child(7) { height: 28px; }
.bar:nth-child(8) { height: 20px; }
.bar:nth-child(9) { height: 24px; }
.bar:nth-child(10) { height: 16px; }
.bar:nth-child(11) { height: 20px; }
.bar:nth-child(12) { height: 12px; }

.albumInfo {
  text-align: center;
}

.albumBadge {
  display: inline-block;
  padding: 4px 12px;
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--vt-accent);
  background: var(--vt-surface-deep);
  border-radius: 20px;
  margin-bottom: 0.5rem;
}

.albumInfo h3 {
  font-size: 1.25rem;
  margin-bottom: 4px;
}

.albumInfo p {
  font-size: 0.875rem;
  color: var(--vt-ink-soft);
  margin-bottom: 0;
}

.about {
  background: var(--vt-surface-2);
}

.aboutGrid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 4rem;
  align-items: center;
}

.aboutImageWrap {
  aspect-ratio: 4 / 5;
  background: var(--vt-line);
  border-radius: 8px;
  overflow: hidden;
  max-width: 280px;
}

.aboutImageWrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.aboutText p {
  color: var(--vt-ink-soft);
  font-size: 1.0625rem;
}

.aboutText p:last-child {
  margin-bottom: 0;
}

.sectionLabel {
  display: block;
  font-family: var(--vt-font-body);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--vt-accent);
  margin-bottom: 0.5rem;
}

.servicesGrid,
.workGrid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

.serviceCard {
  display: flex;
  flex-direction: column;
  padding: 2rem;
  background: var(--vt-on-deep);
  border: 1px solid var(--vt-line);
  border-radius: 8px;
  transition: border-color 0.2s ease;
}

.serviceCard:hover {
  border-color: var(--vt-accent);
}

.serviceIcon {
  width: 64px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--vt-surface-deep);
  border-radius: 8px;
  margin-bottom: 1rem;
  color: var(--vt-accent);
}

.serviceNum {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--vt-accent);
  margin-bottom: 0.25rem;
}

.serviceCard h3 {
  margin-bottom: 1rem;
}

.serviceCard p {
  color: var(--vt-ink-soft);
  margin-bottom: 1rem;
}

.serviceMeta {
  margin-top: auto;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  padding-top: 0.75rem;
  border-top: 1px solid var(--vt-line);
  font-size: 0.875rem;
  color: var(--vt-ink-soft);
}

.work {
  background: var(--vt-surface-2);
}

.workCard {
  background: var(--vt-on-deep);
  border: 1px solid var(--vt-line);
  border-radius: 8px;
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.workCard:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 32px color-mix(in srgb, var(--vt-ink) 8%, transparent);
}

.workImage {
  aspect-ratio: 16 / 10;
  background: var(--vt-line);
  overflow: hidden;
}

.workImage img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.workInfo {
  padding: 1rem 2rem 2rem;
}

.workCategory {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--vt-accent);
  margin-bottom: 0.5rem;
}

.workInfo h3 {
  margin-bottom: 0.5rem;
}

.contact {
  background: var(--vt-surface-deep);
  padding: 6rem 0;
}

.contactGrid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  align-items: center;
}

.contactInfo h2 {
  margin-bottom: 0.5rem;
}

.contactInfo p {
  color: var(--vt-ink-soft);
  margin-bottom: 1rem;
}

.socialLinks {
  display: flex;
  gap: 0.5rem;
  margin-top: 1rem;
}

.socialLinks a {
  width: 40px;
  height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--vt-on-deep);
  border-radius: 50%;
  color: var(--vt-ink);
  transition: background-color 0.2s ease, color 0.2s ease;
}

.socialLinks a:hover {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
}

.contactAside {
  background: var(--vt-on-deep);
  border: 1px solid var(--vt-line);
  border-radius: 8px;
  padding: 1.5rem;
  overflow: hidden;
}

.footer {
  padding: 2rem 0;
  background: var(--vt-surface);
  border-top: 1px solid var(--vt-line);
}

.footerInner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}

.footerCopyright,
.footerCredit {
  font-size: 0.875rem;
  color: var(--vt-ink-soft);
  margin: 0;
}

.footerCredit:hover {
  color: var(--vt-accent);
}

.root a:focus-visible,
.root button:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

@media (min-width: 640px) {
  .servicesGrid {
    grid-template-columns: repeat(2, 1fr);
  }
  .workGrid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 768px) {
  .aboutGrid {
    grid-template-columns: 1fr 1.5fr;
  }
  .aboutImageWrap {
    max-width: none;
  }
  .servicesGrid {
    grid-template-columns: repeat(3, 1fr);
  }
  .workGrid {
    grid-template-columns: repeat(3, 1fr);
  }
  .contactGrid {
    grid-template-columns: 1fr 1.5fr;
    gap: 4rem;
  }
}

@media (min-width: 900px) {
  .heroGrid {
    grid-template-columns: 1fr 1fr;
    gap: 6rem;
  }
  .albumCover {
    width: 340px;
    height: 340px;
  }
}

@media (max-width: 767px) {
  .navInner {
    flex-wrap: wrap;
    height: auto;
    padding: 0.75rem 0;
  }
  .navLinks {
    order: 2;
    width: 100%;
    justify-content: space-between;
    gap: 0.75rem;
  }
  .navLinks a {
    font-size: 0.875rem;
  }
  .hero {
    padding-top: 4rem;
  }
}
